def restart_grip_reader(block_number):
    time.sleep(0.5)
    grip_device_reader(block_number)
    
# Create the function which listens to the data coming from the CurDes grip device
def on_data(data):
    """ Updates shared values continuously """
    global temp_grip_value    
    temp_grip_value = data[1] + data[2] * 255
    #print(temp_grip_value)
    
# Windows API constants
VK_5 = 0x35  # Virtual key code for '5'

def is_key_pressed(vk_code):
    """Check if a key is currently pressed using Windows API"""
    return ctypes.windll.user32.GetAsyncKeyState(vk_code) & 0x8000 != 0

def grip_device_reader(block_number):
    """ Reads data from the CurDes grip device and updates shared memory """
    print("[Threading Process] Started!")
    # List all connected HID devices
    # Initialize the CurDes device
    devices = hid.HidDeviceFilter(vendor_id=0x181B, product_id=0x0015).get_devices()
    device = devices[0]
    device.open()

    print("[Threading Process] Listening for grip data...")

    # Import the global variables for the process communication
    global threading_running, trial_running, sub_id, temp_grip_value, key_pressed
    # Create array for the data
    data = []
    # Create deque for storing the temp grip data
    temp_grip_value = deque(maxlen=1)
    temp_grip_value = 0
    # Set the threading as running 
    threading_running = True
    # Set the trial as not running 
    trial_running = False
    # Set that no trigger is received right now
    key_5_was_pressed = False
    
    if not devices:
        print("[Threading Process] No device connected, starting the measurment again")
        restart_grip_reader(block_number)
        device.close()
        return 
    # Create the trigger listener
    device.set_raw_data_handler(on_data)
    
    
    #sim_data_counter = 0 # Sim data!
    

    while threading_running:
        
        while trial_running:
            #temp_grip_value = sim_data[sim_data_counter] # Sim data!
            data.append([temp_grip_value, time.time()])

            # Check for trigger, if trigger is there exchange value with -5000
            key_5_is_pressed = is_key_pressed(VK_5)
            # Detect key press (edge detection - only trigger on press, not hold)
            if key_5_is_pressed and not key_5_was_pressed:
                # Save your value here
                data.append([5000, time.time()])
            key_5_was_pressed = key_5_is_pressed
                
            time.sleep(0.005) # NEEDS to be smaller than device sampling rate!
            #sim_data_counter = sim_data_counter +1

        # Set one value to something special, to show the trial has ended
        data.append([10000, time.time()])

        while not trial_running:
            #temp_grip_value = sim_data[sim_data_counter] # Sim data!
            data.append([temp_grip_value, time.time()])

            # Check for trigger, if trigger is there exchange value with -5000
            key_5_is_pressed = is_key_pressed(VK_5)
            # Detect key press (edge detection - only trigger on press, not hold)
            if key_5_is_pressed and not key_5_was_pressed:
                # Save your value here
                data.append([5000, time.time()])
            key_5_was_pressed = key_5_is_pressed

            if not threading_running:
                break
            time.sleep(0.005)  # NEEDS to be smaller than device sampling rate!
            #sim_data_counter = sim_data_counter +1
        
        # Set one value to something special, to show the trial has started
        data.append([20000, time.time()])

    device.close()
    print("[Threading Process] Device closed.")

    # After the measurement has stopped, save the file
    full_path = os.path.join("Results", sub_id , "Force_Profiles", f"grip_force_sub_{sub_id}_block_{block_number}.csv")
    df_saving = pd.DataFrame(data)#, columns=['test', 'grip_force', 'timestamp'])
    df_saving.to_csv(full_path, index=False)



class AssetManager:
    def __init__(self):
        pg.init()  # Ensure pygame is initialized here
        self.screen_info = pg.display.Info()  # Fetch screen information
        self.screen_width = self.screen_info.current_w  # Screen width
        self.screen_height = self.screen_info.current_h  # Screen height
        self.screen = pg.display.set_mode((self.screen_width, self.screen_height), pg.DOUBLEBUF | pg.HWSURFACE, pg.FULLSCREEN)  # Create the screen
        self.bottom_line = self.screen_height * 0.88
        # Base resolution for scaling
        self.base_width, self.base_height = 1920, 1080
        self.scaling_factor_w = self.screen_width / self.base_width
        self.scaling_factor_h = self.screen_height / self.base_height
        
        self.images = {}
        self.fonts = {}
        self.colors = {}
        self.texts = {}
        
        self.load_assets ()
        


    def load_assets(self):
        # Colors
        self.colors = {
            "white": (255, 255, 255),
            "black": (0, 0, 0),
            "red": (255, 0, 0),
            "blue": (0, 0, 255),
        }

        # Fonts
        self.fonts["heading"] = pg.font.SysFont("corbel", 90, bold=True)
        self.fonts["regular"] = pg.font.Font(None, 74)
        self.fonts["important"] = pg.font.SysFont("corbel", 60, bold = False)
        self.fonts["very_important"] = pg.font.SysFont("corbel", 80, bold = True)
        self.fonts["huge"] = pg.font.SysFont("corbel", 150, bold = True)

        # Images
        self.images["bg"] = pg.image.load("Images/Background_1920_1080_fullblue.png")
        self.images["Pizza_chief"] = pg.image.load("Images/Pizza_chief.png")
        self.Pizza_chief_width, self.Pizza_chief_height = self.images["Pizza_chief"].get_size()
        self.images["Pizza_chief_unconscious"] = pg.image.load("Images/Background_1920_1080_fullblue_unconscious.png")
        self.images["pizza"] = self.resize_image(pg.image.load("Images/Pizza.png"), 0.05)
        self.images["middle_pipe"] = self.resize_image(pg.image.load("Images/pipe_bottom_small.png"), 0.05)
        self.middle_wall_width, self.middle_wall_height = self.images["middle_pipe"].get_size()
        self.images["l_wall"] = pg.image.load("Images/left_wall_10.png")
        self.images["r_wall"] = pg.image.load("Images/right_wall_10.png")
        self.images["t_wall"] = pg.image.load("Images/top_wall.png")
        self.images["ukk_logo"] = pg.image.load("Images/UKK_Logo.png")
        # When loading your assets, scale it down
        original_bf_s = pg.image.load("Images/Breakfast_small.png")
        self.images["breakfast_small"] = pg.transform.scale(original_bf_s, (original_bf_s.get_width() * 1, original_bf_s.get_height() * 1 ))
        original_bf_b = pg.image.load("Images/Breakfast_big.png")
        self.images["breakfast_big"] = pg.transform.scale(original_bf_b, (original_bf_b.get_width() * 0.45, original_bf_b.get_height() * 0.45 ))
        
    

        # Pre-render static text
        self.texts["welcome"] = self.render_text("Willkommen zur Studie", "heading", "black")
