    def load_difficulty(self, subject_ID):
        # Load the calibration file
        try:
            dataframe_calibration_settings = pd.read_csv(f'Results/{subject_ID}/final_settings.csv')
            print(dataframe_calibration_settings)
            # Convert the setting into percent
            left_diff_percent = str(round(((dataframe_calibration_settings.iloc[0, 0] - 0.36) /  (0.7 - 0.36)) * (-100) + 100))
            print("Left wall in percent", left_diff_percent)
            right_diff_percent = str(round((0.95 - dataframe_calibration_settings.iloc[0, 1]) / (0.95 - 0.623) * 100))
            print("Right wall in percent", right_diff_percent)

            return left_diff_percent, right_diff_percent
        except Exception as e:
            print(f"Unexpected error when loading calibration: {e}")
            return "", ""
        print() 

