    def max_force_test(self, block_number):
        global threading_running, trial_running, temp_grip_value
        
        # Wait for half a second to let the old threading close properly
        time.sleep(0.5)
        # Start the grip reader thread
        sampler_thread = threading.Thread(target=grip_device_reader, args=(block_number,))
        sampler_thread.start()
        # Wait a short time
        time.sleep(0.05)

        def calculate_scaling_factor(maximum_force):
            global scaling_factor_max_force
            """Calculate factor to scale grip force to Pizza_chiefs height"""
            # To not receive an error, the maximum force can't be 0
            if maximum_force < 1:
                maximum_force = 1
            # Target: Half max grip should move Pizza_chief just above the pipe
            jump_height = self.assets.Pizza_chief_height + self.assets.middle_wall_height
            scaling_factor_max_force = jump_height / (maximum_force / 2)

        def test_repetition(gripBaselineMaxForce):
            global temp_grip_value, threading_running, trial_running
            maximum_force = 0
            running = True
            counter = -5
            last_time = pg.time.get_ticks()
            while running:
                for event in pg.event.get():
                    if event.type == pg.QUIT or (event.type == pg.KEYDOWN and event.key == pg.K_ESCAPE):
                        threading_running = False
                        trial_running = False
                        pg.quit()
                        sys.exit()
                
                now = pg.time.get_ticks()
                dt = (now - last_time) / 1000
                last_time = now
                counter += dt
                            
                # Set when the measurement should end
                if counter > 0:
                    running = False

                # Set the background and texts
                self.assets.screen.fill(self.assets.colors["white"])
                self.assets.screen.blit(self.assets.images["ukk_logo"], (self.assets.screen_width * 0.5 - self.assets.images["ukk_logo"].get_width() / 2, 0))
                self.assets.screen.blit(self.assets.texts["max_force"], (self.assets.screen_width * 0.5 - self.assets.texts["max_force"].get_width() / 2, self.assets.screen_height * 0.3))
                self.assets.screen.blit(self.assets.texts["force_counter_current"], (self.assets.screen_width * 0.4 - self.assets.texts["force_counter_current"].get_width() / 2, self.assets.screen_height * 0.45))
                self.assets.screen.blit(self.assets.texts["force_counter_max"], (self.assets.screen_width * 0.4 - self.assets.texts["force_counter_max"].get_width() / 2, self. assets.screen_height * 0.64))

                # Set the maximum force as the higher of the current and old maximum
                maximum_force = max(maximum_force, (temp_grip_value - gripBaselineMaxForce))
                # Render the current/max force
                text_current_force = self.assets.fonts["huge"].render(f"{temp_grip_value - gripBaselineMaxForce}", True, self.assets.colors["red"])
                text_max_force = self.assets.fonts["huge"].render(f"{maximum_force}", True, self.assets.colors["red"])
                # Draw the current/max force
                self.assets.screen.blit(text_current_force, (self.assets.screen_width * 0.6 , self.assets.screen_height * 0.40))
                self.assets.screen.blit(text_max_force, (self.assets.screen_width * 0.6 , self.assets.screen_height * 0.60))
                # Update the screen
                pg.display.update()

                time.sleep(0.005)
            # After the measurement, return the max force of this repetition
            return maximum_force

        # Calculate the baseline
        isCalibrationValid = False
        # Maximum range of force values we consider acceptable during the calibration
        maxRange = 6
        # We calibrate as long as the range is too high
        while (not isCalibrationValid):
            # Instead of measuring for a certain time, we will collect for a set number of points 
            # As 1000/15 = 66, we will include some puffer and set 50 points as goal
            calibration_array = np.zeros(50) # Create an empty array
            # As long as the counter is > 0, keep measuring
            counter = 50
            while counter > 0:  
                # start reading
                calibration_array[50-counter]= temp_grip_value
                counter = counter -1
                time.sleep(0.015)
            baselineRange = np.ptp(calibration_array)
            # check if calibration worked
            isCalibrationValid = baselineRange <= maxRange     
        # save baseline value
        gripBaselineMaxForce = int(np.mean(calibration_array))
            


        # Start of the function
        # Set the variables for the two repetitions
        maximum_force_1 = test_repetition(gripBaselineMaxForce)

        # Have a brake after the first maximum grip test
        counter = -10
        running = True
        while running:
            for event in pg.event.get():
                if event.type == pg.QUIT or (event.type == pg.KEYDOWN and event.key == pg.K_ESCAPE):
                    threading_running = False
                    trial_running = False
                    pg.quit()
                    sys.exit()
                
                # If the event is the space bar then the task continues
                if event.type == pg.KEYDOWN and event.key == pg.K_SPACE:
                    running = False
        
            # Show brake text
            self.assets.screen.fill(self.assets.colors["white"])
            self.assets.screen.blit(self.assets.images["ukk_logo"], (self.assets.screen_width * 0.5 - self.assets.images["ukk_logo"].get_width() / 2, 0))
            self.assets.screen.blit(self.assets.texts["brake_text_1"], (self.assets.screen_width * 0.5 - self.assets.texts["brake_text_1"].get_width() / 2, self.assets.screen_height * 0.3))
            self.assets.screen.blit(self.assets.texts["brake_text_2"], (self.assets.screen_width * 0.5 - self.assets.texts["brake_text_2"].get_width() / 2, self.assets.screen_height * 0.5))
            # Update the screen
            pg.display.update()

        # Second maximum grip test
        maximum_force_2 = test_repetition(gripBaselineMaxForce)
        # Define the maximum force from the two repetitions
        maximum_force = max(maximum_force_1, maximum_force_2)
        # Calculate the scaling factor
        calculate_scaling_factor(maximum_force)
        print(f"The maximum force was: ", maximum_force)
        # Close the grip listening device
        threading_running = False
        return maximum_force       


    def task(self, block_number, positions_dataframe):
        """Runs multiple trials in a block before exiting."""
        # Import the global variables
        global threading_running, trial_running, temp_grip_value

        # define a nested function to draw the image while the countdown is running
        def countdown_update(start_time, delay_time, screenshot, countdown_text):
            if pg.time.get_ticks() - start_time < delay_time:
                countdown_text = self.assets.fonts["regular"].render(f"Start in {round((delay_time - (pg.time.get_ticks()-start_time))/1000, 1)}", True, self.assets.colors["red"])
            # Draw the image
            self.assets.screen.blit(screenshot, (0, 0))
            Pizza_chief.draw(self.assets.screen)
            self.assets.screen.blit(countdown_text, (50, 50))
            self.assets.screen.blit(self.assets.images["pizza"], (self.assets.screen_width * 0.9, self.assets.screen_height * 0.7))
            pg.display.update()
        

        # Empty out the data Frame for the new block
        self.sub_data.drop(self.sub_data.index, inplace=True)

        # Define the amount of trails from the length of the trial types
        num_trials = len(positions_dataframe)

        # Before starting a block, we wait for the first trigger
        running_Trigger = True
        while running_Trigger:
            self.assets.screen.fill(self.assets.colors["white"])
            pg.display.update()
            # Check for trigger, if trigger is there start the block
            key_5_is_pressed = is_key_pressed(VK_5)
            # Detect key press (edge detection - only trigger on press, not hold)
            if key_5_is_pressed and not key_5_was_pressed:
                running_Trigger = False
                self.assets.screen.blit(self.assets.images["bg"], (0, 0))
                pg.display.update()
            key_5_was_pressed = key_5_is_pressed


        for trial in range(num_trials):  # Run multiple trials
            print(f"Starting Trial {trial+1} in Block {block_number-1}")

            # Set the global trial_running variable to true
            trial_running = True

            # Depending on type of trial, define the left and right walls
            trial_diff_left = ((positions_dataframe.left_wall_positions[trial]-100)/-100) * (0.7 - 0.36) + 0.36 # The higher the number further left the wall. Maximum difficulty: 0.36 Minimum difficulty: 0.7
            trial_diff_right = 0.95 - (positions_dataframe.right_wall_positions[trial]/100) * (0.95-0.623) # The higher the number the further right the wall. Maximum difficulty: 0.623 Minimum difficulty: 0.95

            # Save the setting into the data frame
            self.sub_data.at[trial+1, 'Trail_Num'] = trial+1
            self.sub_data.at[trial+1, 'Sub_ID'] = sub_id
            self.sub_data.at[trial+1, 'Diff_left'] = positions_dataframe.left_wall_positions[trial]
            self.sub_data.at[trial+1, 'Diff_right'] = positions_dataframe.right_wall_positions[trial]
            self.sub_data.at[trial+1, 'Type'] = positions_dataframe.trial_type[trial]


            # Initialize Pizza_chief for this trial
            Pizza_chief = Chief(self.assets.images["Pizza_chief"]) 
    
            # Pre-render static assets
            self.assets.screen.blit(self.assets.images["bg"], (0, 0))
            self.assets.screen.blit(self.assets.images["t_wall"], (self.assets.screen_width * 0.2, self.assets.screen_height * 0.0))
            self.assets.screen.blit(self.assets.images["l_wall"], (-self.assets.screen_width * trial_diff_left, self.assets.screen_height * 0.5))
            self.assets.screen.blit(self.assets.images["r_wall"], (self.assets.screen_width * trial_diff_right, -self.assets.screen_height * 0.1))
            self.assets.screen.blit(self.assets.images["middle_pipe"], (self.assets.screen_width * 0.5, self.assets.bottom_line - self.assets.middle_wall_height))


            # Capture initial screen for updating
            pg.image.save(self.assets.screen, "screenshot.jpg")
            screenshot = pg.image.load("screenshot.jpg")        

            delay_time = 2100  # 2,1-second countdown before Pizza_chief starts
            countdown_text = self.assets.fonts["regular"].render("", True, self.assets.colors["white"])
            last_time = pg.time.get_ticks()
            running = True
            isCalibrationValid = False
            start_time = pg.time.get_ticks()
            self.sub_data.at[trial+1, 'Trail_Start'] = time.time() # The start time is right before Pizza_chief starts moving
    
            while running:
                now = pg.time.get_ticks()
                dt = (now - last_time) / 1000
                last_time = now
    
                # Calculation of baseline if there has not been set a baseline in this trial
                if isCalibrationValid == False:
                    # Duration of the acquisition used for computing the baseline, in miliseconds
                    calibrationDuration = 1000
                    # Maximum range of force values we consider acceptable during the calibration
                    maxRange = 6
                    # Define a counter for the number of calibrations 
                    nCalibration = 0
                    # we calibrate as long as the range is too high, if we still have time
                    while (not isCalibrationValid) and ((pg.time.get_ticks() + calibrationDuration) < (start_time + delay_time)):
                        # Instead of measuring for a certain time, we will collect a set number of points 
                        # As 1000/15 = 66, we will include some puffer and set 50 points as goal
                        # Create an empty array
                        calibration_array = np.zeros(50)
                        # As long as the remaining time is > 0, keep measuring
                        counter = 50
                        while counter > 0:  # Run until 50 measuremnts are reached
                            # start reading
                            calibration_array[50-counter]= temp_grip_value
                            counter = counter -1
                            time.sleep(0.015)
                            # Draw the timer on the screen
                            countdown_update(start_time, delay_time, screenshot, countdown_text)
                            # Check if the ESC button was pressed
                            self.stop_function(block_number)
                        # Calculate the range and check if it is lower than the allowed maximal range
                        baselineRange = np.ptp(calibration_array)
                        isCalibrationValid = baselineRange <= maxRange # If true, the while loop ends
                        # Keep track of the number of recalibration
                        nCalibration = nCalibration + 1     
                        # Check if the ESC button was pressed
                        self.stop_function(block_number)   

                    # save baseline value
                    if isCalibrationValid:
                        gripBaseline = int(np.mean(calibration_array))
                        print("The calibration needed ", nCalibration, " calibrations")
                    else:
                        if trial > 0:
                            # Use the baseline from the previous trial
                            gripBaseline = self.sub_data.at[trial, 'Force_Baseline']
                        else:
                            gripBaseline = 0 # In the first overall trial there is no previous baseline
                        print("The calibration was unsuccessful and the previous baseline is used")
                    self.sub_data.at[trial+1, 'Force_Baseline'] = gripBaseline
                    print("The force baseline for this trial is: ", gripBaseline)

                # Run down the timer until the game starts
                countdown_update(start_time, delay_time, screenshot, countdown_text)
                self.clock.tick(60)
                
            
                # If this is given then the trail start and Pizza_chief begins moving
                if pg.time.get_ticks() - start_time >= delay_time:
                    """ This it the part that actually moves Pizza_chief """
                    Pizza_chief.update(dt, gripBaseline)
                    Pizza_chief_rects = Pizza_chief.get_rects()
                    collision, collision_side = self.collisions(Pizza_chief_rects, trial_diff_left, trial_diff_right)
                    # Check if the ESC button was pressed
                    self.stop_function(block_number)

                    if collision == "fail":
                        # Change the trial running variable to false
                        trial_running = False
                        # Save the trial as failed and the time
                        self.sub_data.loc[trial+1, 'Trial_Fail'] = "Fail"
                        self.sub_data.at[trial+1, 'Trial_End'] = time.time()
                        self.sub_data.loc[trial+1, 'Fail_Location'] = collision_side

                        # Draw the screen and then wait 3 sec
                        self.assets.screen.blit(self.assets.images["Pizza_chief_unconscious"], (0, 0))
                        self.screen_timer(block_number, time_type="feedback")
                        # Show the intertrial interval as a jittered 8.5 sec
                        self.screen_timer(block_number, time_type="jitter")
                        break  # Move to the next trial
                    
                    if collision == "success":
                        # Change the trial running variable to false
                        trial_running = False
                        # Save the trial as success and the time
                        self.sub_data.loc[trial+1, 'Trial_Fail'] = "Success"
                        self.sub_data.at[trial+1, 'Trial_End'] = time.time()
                        self.sub_data.loc[trial+1, 'Fail_Location'] = "None"
                        # Start the celebration function
                        print("Successfully collected the pizza!")
                        self.celebration(block_number)
                        # Show the intertrial interval as a jittered 8.5 sec
                        self.screen_timer(block_number, time_type="jitter")
                        print("Restarting next trial...")
                        break  # Move to the next trial


        print(f"Block {block_number-1} complete!")
        # End the force recording
        running = False
        trial_running = False


    def save_overview(self, block_number):
        global sub_id
        # Save the data frame for this block
        full_path = os.path.join("Results", sub_id , f"Trial_overview_sub_{sub_id}_Block_{block_number}.csv")
        df_saving = pd.DataFrame(self.sub_data, columns=['Sub_ID', 'Trail_Num', 'Type', 'Trial_Fail', 'Trail_Start', 'Trial_End', 'Fail_Location', 'Diff_left','Diff_right', 'Force_Baseline'])
        df_saving.to_csv(full_path, index=False)
        
        print(f"Saved the overview file under: " + full_path)
        
    # Function to stop the game if ESC has been pressed
    def stop_function(self, block_number):
        # Import the global running variable
        global threading_running, trial_running
        for event in pg.event.get():
            if event.type == pg.QUIT or (event.type == pg.KEYDOWN and event.key == pg.K_ESCAPE):
                trial_running = False
                threading_running = False # This leads to the grip device stopping the measurement
                self.save_overview(block_number)
                pg.quit()
                sys.exit()

    # Function for the inter-trial interval
    def screen_timer(self, block_number, time_type):
        if time_type == "jitter":
            # Draw the screen and then wait jittered time period
            self.assets.screen.blit(self.assets.images["bg"], (0, 0))
            counter = -(random.uniform(6, 11))
        else:
            # Keep the feedback screen and wait a fixed 3 second period
            counter = -3
        running = True
        last_time = pg.time.get_ticks()
        while running:
            now = pg.time.get_ticks()
            dt = (now - last_time) / 1000
            last_time = now
            counter += dt
                        
            # Fail animation stop
            if counter > 0:
                running = False
                                
            # Check if the ESC button was pressed
            self.stop_function(block_number)
                            
            pg.display.flip()
            self.clock.tick(60)
    
            
    def collisions(self, Pizza_chief_rects, trial_diff_left, trial_diff_right):
        """Check if Pizza_chief collides with any static object or the pizza."""
        Pizza_chief_top_rect, Pizza_chief_middle_rect, Pizza_chief_bottom_rect = Pizza_chief_rects
    
        start_wall_rect = pg.Rect(
            0,
            0,
            self.assets.screen_width *0.08,
            self.assets.screen_height*0.6
        )
        top_wall_rect = pg.Rect(
            self.assets.screen_width * 0.2,
            self.assets.screen_height * 0.0,
            self.assets.images["t_wall"].get_width(),
            self.assets.images["t_wall"].get_height(),
        )

        middle_wall_bottom_rect = pg.Rect(
            self.assets.screen_width * 0.5,
            self.assets.bottom_line - self.assets.middle_wall_height,
            self.assets.images["middle_pipe"].get_width(),
            self.assets.images["middle_pipe"].get_height(),
        )

        left_wall_rect = pg.Rect(
            -self.assets.screen_width * trial_diff_left,
            self.assets.screen_height * 0.5,
            self.assets.images["l_wall"].get_width(),
            self.assets.images["l_wall"].get_height(),
        )
        right_wall_rect = pg.Rect(
            self.assets.screen_width * trial_diff_right,
            -self.assets.screen_height * 0.1,
            self.assets.images["r_wall"].get_width(),
            self.assets.images["r_wall"].get_height(),
        )

        pizza_rect = pg.Rect(
            self.assets.screen_width * 0.9, 
            self.assets.screen_height *0.7,
            self.assets.images["pizza"].get_width(),
            self.assets.images["pizza"].get_height(),
        )
        collision_detected = None
        collision_side = None
        
        if (Pizza_chief_bottom_rect.colliderect(middle_wall_bottom_rect)
            or Pizza_chief_middle_rect.colliderect(middle_wall_bottom_rect)
        ):
            # Create a rectangle representing the left side of the wall
            left_side_rect = pg.Rect(middle_wall_bottom_rect.left, 
                                    middle_wall_bottom_rect.top, 
                                    1,  # 1 pixel wide
                                    middle_wall_bottom_rect.height)  # full height
            if (Pizza_chief_bottom_rect.colliderect(left_side_rect) or
                Pizza_chief_middle_rect.colliderect(left_side_rect)):
                collision_side = "middle_wall_up" 
                collision_detected = "fail"
            else:
                collision_side = "middle_wall_down"
                collision_detected = "fail"

            
        if (Pizza_chief_top_rect.colliderect(right_wall_rect)
            or Pizza_chief_middle_rect.colliderect(right_wall_rect)
            or Pizza_chief_bottom_rect.colliderect(right_wall_rect)
        ):
            collision_side = "right_wall"
            collision_detected = "fail"
            

        elif (Pizza_chief_top_rect.colliderect(left_wall_rect)
            or Pizza_chief_middle_rect.colliderect(left_wall_rect)
            or Pizza_chief_bottom_rect.colliderect(left_wall_rect)
            or Pizza_chief_top_rect.colliderect(start_wall_rect)
            or Pizza_chief_middle_rect.colliderect(start_wall_rect)
            or Pizza_chief_bottom_rect.colliderect(start_wall_rect)
        ):
            collision_side = "left_wall"
            collision_detected = "fail"

        elif (Pizza_chief_top_rect.colliderect(top_wall_rect)
            or Pizza_chief_middle_rect.colliderect(top_wall_rect)
            or Pizza_chief_bottom_rect.colliderect(top_wall_rect)
        ):
            collision_side = "top_wall"
            collision_detected = "fail"

            
        elif (Pizza_chief_top_rect.colliderect(pizza_rect)
            or Pizza_chief_middle_rect.colliderect(pizza_rect)
            or Pizza_chief_bottom_rect.colliderect(pizza_rect)
        ):
            collision_detected = "success"
            
        return collision_detected, collision_side

            
    def celebration(self, block_number):
        """Handle the celebration animation after Pizza_chief collects the pizza."""
        global threading_running, trial_running

        # Calculate and draw the total reward
        self.total_reward = self.total_reward + 1
        new_reward = self.assets.fonts["huge"].render(f"x {self.total_reward}", True, self.assets.colors["red"])
        resized_pizza_counter = pg.transform.scale(self.assets.images["pizza"], (self.assets.images["pizza"].get_width() * 2, self.assets.images["pizza"].get_height() * 2))
        self.assets.screen.blit(self.assets.texts["success"], (self.assets.screen_width/2 - self.assets.texts["success"].get_width()/2, self.assets.screen_height/3 - self.assets.images["pizza"].get_height()*2))
        self.assets.screen.blit(self.assets.texts["pizza_counter_neu"], (self.assets.screen_width * 0.25 , self.assets.screen_height * 0.40))
        self.assets.screen.blit(resized_pizza_counter, (self.assets.screen_width * 0.43 , self.assets.screen_height * 0.35))
        self.assets.screen.blit(new_reward, (self.assets.screen_width * 0.55 , self.assets.screen_height * 0.35))
        
        # Show for 3 sec
        self.screen_timer(block_number, time_type="feedback")
        
    def brake(self):
        """Shows the brake screen between blocks."""
        global threading_running, trial_running

        # Show the brake text
        self.assets.screen.fill(self.assets.colors["white"])
        self.assets.screen.blit(self.assets.images["ukk_logo"], (self.assets.screen_width * 0.5 - self.assets.images["ukk_logo"].get_width() / 2, 0))
        self.assets.screen.blit(self.assets.texts["brake_text_1"], (self.assets.screen_width * 0.5 - self.assets.texts["brake_text_1"].get_width() / 2, self.assets.screen_height * 0.3))
        self.assets.screen.blit(self.assets.texts["brake_text_2"], (self.assets.screen_width * 0.5 - self.assets.texts["brake_text_2"].get_width() / 2, self.assets.screen_height * 0.5))
        running = True
        while running:   
            # Handle events
            for event in pg.event.get():
                if event.type == pg.QUIT or (event.type == pg.KEYDOWN and event.key == pg.K_ESCAPE):
                    running = False
                    trial_running = False
                    threading_running = False
                    pg.quit()
                    sys.exit()
                
                # If the event is the space bar then the task continues
                if event.type == pg.KEYDOWN and event.key == pg.K_SPACE:
                    running = False

            pg.display.flip()
            self.clock.tick(60)

    def experiment(self, block_number_extern):
        """Runs the task in a block structure while allowing the researcher to set the number of blocks."""
        # Import the block number
        block_number = block_number_extern


        def init_block(left_wall_positions, right_wall_positions, trial_types_list, block_number):
            global threading_running
            # Start the new grip reader thread
            sampler_thread = threading.Thread(target=grip_device_reader, args=(block_number,))
            sampler_thread.start()
            # Convert to DataFrame (transpose to have rows as data points)
            positions_dataframe = pd.DataFrame([trial_types_list, left_wall_positions, right_wall_positions]).T
            positions_dataframe.columns = ['trial_type', 'left_wall_positions', 'right_wall_positions']
            print(positions_dataframe)
            # Start the task
            self.task(block_number, positions_dataframe)
            self.save_overview(block_number)
            self.brake()
            threading_running = False # End the grip reader thread


        # --- Training block ---
        # Create the rows for the trail type and difficulty
        left_wall_positions = [25, 0, 50, 0, 80, 0]
        right_wall_positions =[0, 25, 0, 50, 0, 80]
        trial_types_list = ['Wall_L', 'Wall_R', 'Wall_L', 'Wall_R', 'Wall_L', 'Wall_R']
        
        # Start task for the testing block 
        init_block(left_wall_positions, right_wall_positions, trial_types_list, block_number)
        

        # --- Testing blocks ---
        # available blocks
        available_blocks = [
            ['Wall_L', 'Wall_L', 'Wall_R', 'Wall_R'],
            ['Wall_L', 'Wall_R', 'Wall_L', 'Wall_R'],
            ['Wall_R', 'Wall_L', 'Wall_R', 'Wall_L'],
            ['Wall_L', 'Wall_R', 'Wall_R', 'Wall_L'],
            ['Wall_R', 'Wall_L', 'Wall_L', 'Wall_R'],
            ['Wall_R', 'Wall_R', 'Wall_L', 'Wall_L'],
        ]

        # --- Testing block 2 and 3, left and right wall ---
        for i in range(2):
            # Increase the block number
            block_number = block_number + 1
            # Select a random combination of blocks
            selected_blocks = random.choices(available_blocks, k=8)
            # Flatten the blocks into a single list of trial types
            trial_types_list = [item for block in selected_blocks for item in block]
            # Create lists for the wall difficulties
            left_wall_positions = [self.left_wall_diff if item == 'Wall_L' else 0 for item in trial_types_list]
            right_wall_positions = [self.right_wall_diff if item == 'Wall_R' else 0 for item in trial_types_list]

            # Wait for half a second to let the old threading close properly
            time.sleep(0.5)
            # Start task for first testing block
            init_block(left_wall_positions, right_wall_positions, trial_types_list, block_number)

    
    def create_folder(self, directory):
        """Creates folders for storing results."""
        if not os.path.exists(directory):
            os.makedirs(directory)
            # Use os.path.join to handle slashes automatically
            path = os.path.join(directory, "Force_Profiles")
            os.makedirs(path, exist_ok=True)

    def save_grip(self):
        global sub_id
        # Combine the grip forces
        data_maxgrip = {'Max_Grip_Beginning': [self.max_grip], 'Max_Grip_End': [self.max_grip_end]}
        df_saving = pd.DataFrame(data_maxgrip)
        # Save the beginning and ending grip force
        full_path = os.path.join("Results", sub_id , f"max_grip_force_sub_{sub_id}.csv")
        df_saving.to_csv(full_path, index=False)

    def run(self):
        self.introduction()
        self.max_grip = self.max_force_test(block_number=1)
        self.food_reward()
        self.experiment(block_number_extern=2)
        self.max_grip_end = self.max_force_test(block_number=5)
        self.save_grip()
        pg.quit()
        sys.exit()


